using System.IO;

namespace AIHub.Services;

/// <summary>Repair only generated bytecode in music overlays; never relax the pinned source tree.</summary>
internal static class MusicPythonOverlayVerifier
{
    internal static async Task VerifyAsync(string root, IReadOnlyList<PinnedTreeFile> files, CancellationToken token,
        Action<int, int>? progress, Action<string>? log)
    {
        var quarantine = Path.Combine(AppDataPaths.BaseDirectory, "RuntimeCacheQuarantine", "MusicPython",
            Path.GetFileName(root) + "-" + Guid.NewGuid().ToString("N"));
        var moved = 0;
        try
        {
            await PinnedFileTreeVerifier.VerifyAsync(root, files, token, progress,
                ignoredFiles: new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "files.json" },
                pythonCacheQuarantineDirectory: quarantine, cacheQuarantined: _ => moved++);
        }
        finally
        {
            if (moved > 0) log?.Invoke($"[Prepare] Python cache files moved to backup: {moved} · {quarantine}");
        }
    }
}
